#!/usr/bin/env python3
"""BGShare peer - every PC is an equal peer (no central server). Python 3 standard library only.

Each running copy:
  * serves its own UI on http://127.0.0.1:<port>/ (local-only, protected by a per-run token)
  * exposes a peer API on <LAN IP>:<port> for receiving files and snippets from other peers
  * announces itself on the LAN by UDP multicast (+ broadcast fallback) on the discovery port
  * treats every BGShare peer on the LAN as a teammate; transfers are accepted automatically

Traffic is NOT encrypted and not authenticated (plain HTTP on the LAN). Use it on trusted office networks only.

Run headless (for servers/tests):  python bgshare_peer.py --headless --name "Ada" [--port 8890]
The Windows desktop app (bgshare_desktop.py) imports this module and adds the window, tray and toasts.
"""
import argparse, base64, difflib, getpass, hashlib, hmac, http.client, json, logging, mimetypes, os, re, secrets
import shutil, socket, subprocess, sys, threading, time, unicodedata, uuid
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs, quote

APP = "BGShare"
VERSION = "2.1.0"
PROTO = 1
DEFAULT_PORT = 8890                 # TCP: UI + peer API
DISCOVERY_PORT = 8890               # UDP: announcements
MCAST_GRP = "239.255.77.88"        # BGShare's own discovery group, not a host on the LAN
CHUNK = 4 * 1024 * 1024
SNIPPET_MAX = 1024 * 1024
ONLINE_SECS = 16
ANNOUNCE_SECS = 5
CLOCK_SKEW = 300
log = logging.getLogger("bgshare")

# ---------------------------------------------------------------- paths
def app_dir():
    base = os.environ.get("APPDATA") if os.name == "nt" else os.path.join(os.path.expanduser("~"), ".config")
    d = os.path.join(base or os.path.expanduser("~"), APP)
    os.makedirs(d, exist_ok=True)
    return d

def downloads_dir():
    if os.name == "nt":
        try:
            import ctypes
            from ctypes import wintypes
            class GUID(ctypes.Structure):
                _fields_ = [("a", wintypes.DWORD), ("b", wintypes.WORD), ("c", wintypes.WORD), ("d", ctypes.c_ubyte * 8)]
            g = GUID(0x374DE290, 0x123F, 0x4565, (ctypes.c_ubyte * 8)(0x91, 0x64, 0x39, 0xC4, 0x92, 0x5E, 0x46, 0x7B))
            p = ctypes.c_wchar_p()
            if ctypes.windll.shell32.SHGetKnownFolderPath(ctypes.byref(g), 0, None, ctypes.byref(p)) == 0:
                path = p.value; ctypes.windll.ole32.CoTaskMemFree(p)
                return os.path.join(path, APP)
        except Exception:
            pass
    return os.path.join(os.path.expanduser("~"), "Downloads", APP)

def safe_name(name):
    if not name: return None
    name = unicodedata.normalize("NFC", str(name)).replace("\\", "/").split("/")[-1]
    name = re.sub(r'[\x00-\x1f<>:"|?*]', "_", name).strip().strip(".").strip()
    if not name or name in (".", ".."): return None
    if re.match(r"^(CON|PRN|AUX|NUL|COM\d|LPT\d)(\..*)?$", name, re.I): name = "_" + name
    return name[:200]

def unique_path(folder, name):
    base, ext = os.path.splitext(name); cand, i = name, 2
    while os.path.exists(os.path.join(folder, cand)):
        cand = f"{base} ({i}){ext}"; i += 1
    return os.path.join(folder, cand)

def lan_ips():
    ips = set()
    try:
        # UDP connect sends nothing. 192.0.2.1 is the RFC 5737 documentation address, used only so the OS names this PC's LAN address.
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.connect(("192.0.2.1", 1)); ips.add(s.getsockname()[0]); s.close()
    except OSError: pass
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET): ips.add(info[4][0])
    except OSError: pass
    return sorted(i for i in ips if not i.startswith("127.")) or ["127.0.0.1"]

def file_sha256(path, progress=None):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            b = fh.read(CHUNK)
            if not b: break
            h.update(b)
            if progress: progress(len(b))
    return h.hexdigest()

# ---------------------------------------------------------------- categories
CATS = ["video", "image", "audio", "document", "spreadsheet", "slides", "pdf", "archive", "code", "text", "other", "snippet"]
_EXT = {"video": "mp4 mov avi mkv webm m4v wmv flv 3gp mpg mpeg", "image": "png jpg jpeg gif webp svg bmp heic heif tif tiff ico raw",
        "audio": "mp3 wav m4a aac flac ogg wma opus", "document": "doc docx odt rtf pages wpd",
        "spreadsheet": "xls xlsx xlsm csv ods numbers tsv", "slides": "ppt pptx odp key", "pdf": "pdf",
        "archive": "zip rar 7z tar gz tgz bz2 xz iso dmg cab", "text": "txt md log ini cfg conf rst",
        "code": "py js ts jsx tsx html htm css json xml yml yaml sh bat ps1 java c cpp h hpp cs go rs php sql rb kt swift ipynb"}
EXT_CAT = {e: c for c, es in _EXT.items() for e in es.split()}

def category(name, kind="file"):
    if kind == "snippet": return "snippet"
    ext = os.path.splitext(name)[1][1:].lower()
    if ext in EXT_CAT: return EXT_CAT[ext]
    m = mimetypes.guess_type(name)[0] or ""
    for pre, c in (("video/", "video"), ("image/", "image"), ("audio/", "audio"), ("text/", "text")):
        if m.startswith(pre): return c
    if m == "application/pdf": return "pdf"
    return "other"

def human(n):
    for u in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or u == "TB": return f"{n:.0f} {u}" if u == "B" else f"{n:.1f} {u}"
        n /= 1024

# ---------------------------------------------------------------- native clipboard / shell
def copy_to_clipboard(text):
    """Copy text with the OS clipboard (not the browser). Returns True on success."""
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes
        k, u = ctypes.windll.kernel32, ctypes.windll.user32
        k.GlobalAlloc.restype = wintypes.HGLOBAL; k.GlobalAlloc.argtypes = [wintypes.UINT, ctypes.c_size_t]
        k.GlobalLock.restype = wintypes.LPVOID; k.GlobalLock.argtypes = [wintypes.HGLOBAL]
        k.GlobalUnlock.argtypes = [wintypes.HGLOBAL]
        u.OpenClipboard.argtypes = [wintypes.HWND]
        u.SetClipboardData.restype = wintypes.HANDLE; u.SetClipboardData.argtypes = [wintypes.UINT, wintypes.HANDLE]
        data = text.encode("utf-16-le") + b"\x00\x00"
        for _ in range(20):
            if u.OpenClipboard(None): break
            time.sleep(0.05)
        else:
            return False
        try:
            u.EmptyClipboard()
            h = k.GlobalAlloc(0x0002, len(data)); p = k.GlobalLock(h)
            ctypes.memmove(p, data, len(data)); k.GlobalUnlock(h)
            return bool(u.SetClipboardData(13, h))       # CF_UNICODETEXT
        finally:
            u.CloseClipboard()
    for cmd in (["pbcopy"], ["wl-copy"], ["xclip", "-selection", "clipboard"], ["xsel", "--clipboard", "--input"]):
        if shutil.which(cmd[0]):
            try:
                subprocess.run(cmd, input=text.encode("utf-8"), check=True, timeout=5); return True
            except (OSError, subprocess.SubprocessError):
                pass
    return False

def open_path(path, reveal=False):
    if not path or not os.path.exists(path): return False
    try:
        if os.name == "nt":
            if reveal: subprocess.Popen(["explorer", "/select,", os.path.normpath(path)])
            else: os.startfile(path)
        elif sys.platform == "darwin":
            subprocess.Popen(["open", "-R", path] if reveal else ["open", path])
        else:
            subprocess.Popen(["xdg-open", os.path.dirname(path) if reveal else path])
        return True
    except Exception as e:
        log.warning("open failed: %s", e); return False

class Notifier:
    """Headless notifier: logs and keeps the last notifications (the desktop app swaps in Windows toasts)."""
    def __init__(self): self.items = []
    def notify(self, title, body, iid=None):
        self.items.append({"t": time.time(), "title": title, "body": body, "iid": iid}); del self.items[:-100]
        log.info("notify: %s | %s", title, body)

def default_name():
    try: n = getpass.getuser()
    except Exception: n = os.environ.get("USERNAME") or os.environ.get("USER") or ""
    return re.sub(r"[._-]+", " ", n).strip().title()[:40]

HEX32 = re.compile(r"[0-9a-f]{32}")

# ---------------------------------------------------------------- peer
class Peer:
    def __init__(self, data_dir=None, port=DEFAULT_PORT, discovery_port=DISCOVERY_PORT, name=None,
                 download_dir=None, notifier=None, bind="0.0.0.0"):
        self.dir = os.path.abspath(data_dir or app_dir())
        for sub in ("tmp", "versions", "snippets", "staging"): os.makedirs(os.path.join(self.dir, sub), exist_ok=True)
        self.lock = threading.RLock()
        self.cfg = self._load("config.json", {})
        c = self.cfg
        c.setdefault("id", uuid.uuid4().hex); c.setdefault("team", {}); c.setdefault("notify", True); c.setdefault("created", time.time())
        for k in ("code", "accept_mode", "known", "manual"): c.pop(k, None)          # drop settings from 2.0.0
        if name: c["name"] = name
        if download_dir: c["download_dir"] = os.path.abspath(download_dir)
        c.setdefault("download_dir", downloads_dir())
        self.port = int(port); self.discovery_port = int(discovery_port); self.bind = bind
        self.hist = self._load("history.json", {"items": {}})
        self.events = self._load_events()
        self.peers = {}                     # id -> {id,name,ip,port,last_seen}
        self.transfers = {}
        self.offers_in = {}                 # tid -> incoming offer
        self.local_token = secrets.token_urlsafe(24)
        self.notifier = notifier or Notifier()
        self.stopping = False
        self.usock = None
        self._last_announce = 0
        self.save_cfg()
        for n in os.listdir(os.path.join(self.dir, "staging")):
            p = os.path.join(self.dir, "staging", n)
            shutil.rmtree(p, ignore_errors=True) if os.path.isdir(p) else os.remove(p)

    # ---- persistence
    def _load(self, name, default):
        try:
            with open(os.path.join(self.dir, name), encoding="utf-8") as fh: return json.load(fh)
        except (OSError, ValueError): return default
    def _save(self, name, obj):
        p = os.path.join(self.dir, name)
        with self.lock:
            with open(p + ".tmp", "w", encoding="utf-8") as fh: json.dump(obj, fh, indent=1)
            os.replace(p + ".tmp", p)
    def save_hist(self): self._save("history.json", self.hist)
    def save_cfg(self): self._save("config.json", self.cfg)
    def _load_events(self):
        out = []
        try:
            with open(os.path.join(self.dir, "events.jsonl"), encoding="utf-8") as fh:
                for line in fh:
                    try: out.append(json.loads(line))
                    except ValueError: pass
        except OSError: pass
        return out
    def log_event(self, e, kind, size, cat, peer_id=None):
        ev = {"t": round(time.time(), 3), "e": e, "k": kind, "b": size, "c": cat, "p": peer_id}
        with self.lock:
            self.events.append(ev)
            with open(os.path.join(self.dir, "events.jsonl"), "a", encoding="utf-8") as fh: fh.write(json.dumps(ev) + "\n")

    # ---- identity
    @property
    def ready(self): return bool(self.cfg.get("name"))
    @property
    def me(self): return {"id": self.cfg["id"], "name": self.cfg.get("name") or "", "port": self.port}

    def start(self):
        self.httpd = ThreadingHTTPServer((self.bind, self.port), make_handler(self))
        self.httpd.daemon_threads = True
        threading.Thread(target=self.httpd.serve_forever, daemon=True, name="http").start()
        self._start_discovery()
        log.info("BGShare peer %s (%s) on port %d, data %s", self.cfg.get("name"), self.cfg["id"][:8], self.port, self.dir)
        return self

    def stop(self):
        self.stopping = True
        try: self.httpd.shutdown(); self.httpd.server_close()
        except Exception: pass
        try: self.usock.close()
        except Exception: pass

    # ---------------------------------------------------------------- discovery (automatic only)
    def _start_discovery(self):
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        if hasattr(socket, "SO_REUSEPORT"):
            try: s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
            except OSError: pass
        s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        try:
            s.bind(("", self.discovery_port))
        except OSError as e:
            log.error("discovery disabled (UDP %d): %s", self.discovery_port, e); return
        joined = 0
        for ip in ["0.0.0.0"] + lan_ips():
            try:
                s.setsockopt(socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP, socket.inet_aton(MCAST_GRP) + socket.inet_aton(ip)); joined += 1
            except OSError: pass
        s.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_TTL, 1)
        s.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_LOOP, 1)
        self.usock = s
        log.info("discovery on UDP %d (multicast %s, %d memberships)", self.discovery_port, MCAST_GRP, joined)
        threading.Thread(target=self._udp_loop, daemon=True, name="udp-rx").start()
        threading.Thread(target=self._announce_loop, daemon=True, name="udp-tx").start()

    def announcement(self):
        return json.dumps({"app": APP, "proto": PROTO, "id": self.cfg["id"], "name": self.cfg.get("name", ""), "port": self.port}).encode()

    def announce(self):
        if not self.ready or not self.usock: return
        data = self.announcement()
        targets = [(MCAST_GRP, self.discovery_port), ("255.255.255.255", self.discovery_port)]
        for ip in lan_ips():
            if ip.count(".") == 3: targets.append((ip.rsplit(".", 1)[0] + ".255", self.discovery_port))
        for t in targets:
            try: self.usock.sendto(data, t)
            except OSError: pass
        self._last_announce = time.time()

    def _announce_loop(self):
        while not self.stopping:
            self.announce(); time.sleep(ANNOUNCE_SECS)

    def _udp_loop(self):
        while not self.stopping:
            try: data, (ip, _) = self.usock.recvfrom(4096)
            except OSError:
                if self.stopping: return
                continue
            try:
                a = json.loads(data)
                if a.get("app") != APP or a.get("id") == self.cfg["id"] or not self.ready: continue
                if not HEX32.fullmatch(str(a.get("id"))): continue
                port = int(a["port"])
                if not 0 < port < 65536: continue
                new = self.upsert_peer(a["id"], a.get("name", ""), ip, port)
                if new and time.time() - self._last_announce > 0.5:
                    self.announce()                       # let the newcomer see this PC right away
            except (ValueError, KeyError, TypeError):
                continue

    def upsert_peer(self, pid, name, ip, port):
        name = re.sub(r"\s+", " ", str(name)).strip()[:40] or "BGShare PC"
        with self.lock:
            p = self.peers.get(pid); new = p is None or time.time() - p["last_seen"] > ONLINE_SECS
            self.peers[pid] = {"id": pid, "name": name, "ip": ip, "port": port, "last_seen": time.time()}
            t = self.cfg["team"].get(pid)
            if not t or t.get("name") != name or new:
                self.cfg["team"][pid] = {"name": name, "last_seen": time.time(), "since": (t or {}).get("since", time.time())}
                self.save_cfg()
        return new

    def online_peers(self):
        now = time.time()
        with self.lock:
            return [dict(p) for p in self.peers.values() if now - p["last_seen"] <= ONLINE_SECS]

    def team(self):
        online = {p["id"] for p in self.online_peers()}
        out = [{"id": self.cfg["id"], "name": self.cfg.get("name", ""), "you": True, "online": True, "joined": self.cfg["created"]}]
        for pid, t in self.cfg["team"].items():
            if HEX32.fullmatch(pid):
                out.append({"id": pid, "name": t.get("name", ""), "online": pid in online, "last_seen": t.get("last_seen"), "joined": t.get("since")})
        return out

    def name_of(self, pid):
        if pid == self.cfg["id"]: return self.cfg.get("name", "")
        return (self.peers.get(pid) or self.cfg["team"].get(pid) or {}).get("name") or "BGShare PC"

    # ---------------------------------------------------------------- outgoing HTTP
    def _conn(self, peer, timeout=10):
        return http.client.HTTPConnection(peer["ip"], peer["port"], timeout=timeout, blocksize=CHUNK)

    def call(self, peer, method, path, obj=None, timeout=10):
        body = json.dumps(obj).encode() if obj is not None else b""
        c = self._conn(peer, timeout)
        try:
            c.request(method, path, body=body, headers={"Content-Type": "application/json", "X-BG-Id": self.cfg["id"]})
            r = c.getresponse(); data = r.read()
            try: j = json.loads(data or b"{}")
            except ValueError: j = {}
            return r.status, j
        finally:
            c.close()

    # ---------------------------------------------------------------- sending
    def parse_to(self, to):
        """'everyone' / ['everyone'] / 'id1,id2' / [ids] -> ('everyone', None) or (None, [ids])"""
        if isinstance(to, str): to = [x for x in to.split(",") if x]
        to = [str(x) for x in (to or [])]
        if not to or "everyone" in to: return True, []
        return False, [x for x in dict.fromkeys(to) if HEX32.fullmatch(x) and x != self.cfg["id"]]

    def _out_thread(self, kind, name, everyone, ids):
        aud = "everyone" if everyone else ",".join(sorted(ids))
        k = name.casefold()
        for it in self.hist["items"].values():
            if it["dir"] == "out" and it["kind"] == kind and it["name"].casefold() == k and it.get("aud") == aud and not it.get("deleted"):
                return it
        return None

    def _targets(self, everyone, ids):
        online = {p["id"]: p for p in self.online_peers()}
        if everyone: return list(online.values()), []
        return [online[i] for i in ids if i in online], [i for i in ids if i not in online]

    def add_out_version(self, kind, name, everyone, ids, sha, size, note):
        """Record a new sent version (or report unchanged). Returns (item, version_number, unchanged)."""
        with self.lock:
            it = self._out_thread(kind, name, everyone, ids)
            if it and it["versions"][-1]["sha"] == sha:
                return it, len(it["versions"]), True
            if not it:
                it = {"iid": secrets.token_hex(8), "dir": "out", "kind": kind, "name": name, "everyone": everyone,
                      "aud": "everyone" if everyone else ",".join(sorted(ids)),
                      "to": [] if everyone else [{"id": i, "name": self.name_of(i)} for i in ids], "versions": []}
                self.hist["items"][it["iid"]] = it
            it["versions"].append({"sha": sha, "size": size, "time": time.time(), "note": note[:140], "status": {}})
            it["time"] = time.time(); it["size"] = size; self.save_hist()
            return it, len(it["versions"]), False

    def stage_upload(self, name, length, rfile):
        """Stream a file from the local UI into versions/<sha>. Returns (sha, size)."""
        tmp = os.path.join(self.dir, "staging", secrets.token_hex(8))
        h = hashlib.sha256(); left = length
        with open(tmp, "wb") as fh:
            while left > 0:
                b = rfile.read(min(CHUNK, left))
                if not b: break
                fh.write(b); h.update(b); left -= len(b)
        if left > 0:
            os.remove(tmp); raise OSError("upload interrupted")
        sha = h.hexdigest(); dest = os.path.join(self.dir, "versions", sha)
        if os.path.exists(dest): os.remove(tmp)
        else: os.replace(tmp, dest)
        return sha, length

    def send_upload(self, name, length, rfile, to, note=""):
        name = safe_name(name)
        if not name: return 400, {"error": "Invalid file name"}
        everyone, ids = self.parse_to(to)
        if not everyone and not ids: return 400, {"error": "Choose at least one recipient"}
        if not self._targets(everyone, ids)[0]:
            left = length
            while left > 0:
                b = rfile.read(min(CHUNK, left))
                if not b: break
                left -= len(b)
            return 409, {"error": "None of the selected people are online"}
        sha, size = self.stage_upload(name, length, rfile)
        it, v, same = self.add_out_version("file", name, everyone, ids, sha, size, note)
        if same: return 200, {"ok": True, "unchanged": True, "version": v, "id": it["iid"]}
        res = self.deliver(it, v - 1)
        return 200, {"ok": True, "version": v, "id": it["iid"], "results": res,
                     "delivered": sum(1 for r in res if r["ok"]), "recipients": len(res)}

    def deliver(self, it, vi):
        """Send version vi of an outgoing item to its online recipients; waits for the transfers. Returns per-peer results."""
        everyone, ids = it["everyone"], [t["id"] for t in it.get("to", [])]
        peers, offline = self._targets(everyone, ids)
        ver = it["versions"][vi]; res = []
        for pid in offline:
            ver["status"][pid] = "offline"; res.append({"id": pid, "name": self.name_of(pid), "ok": False, "status": "offline"})
        def one(p):
            if it["kind"] == "file": r = self._send_file(p, it, vi)
            else: r = self._send_snippet(p, it, vi)
            ver["status"][p["id"]] = r; res.append({"id": p["id"], "name": p["name"], "ok": r in ("sent", "unchanged"), "status": r})
        ts = [threading.Thread(target=one, args=(p,), daemon=True, name="send-" + p["name"][:10]) for p in peers]
        for t in ts: t.start()
        for t in ts: t.join()
        if any(r["ok"] for r in res):
            self.log_event("send", it["kind"], ver["size"], category(it["name"], it["kind"]), ",".join(r["id"] for r in res if r["ok"]))
        self.save_hist()
        return res

    def _send_file(self, peer, it, vi):
        ver = it["versions"][vi]; path = os.path.join(self.dir, "versions", ver["sha"]); size = ver["size"]
        tid = secrets.token_hex(16)
        tr = {"tid": tid, "dir": "out", "iid": it["iid"], "name": it["name"], "size": size, "done": 0, "peer": peer["name"],
              "peer_id": peer["id"], "status": "Contacting", "start": time.time(), "speed": 0}
        self.transfers[tid] = tr
        offer = dict(self.me, tid=tid, kind="file", fname=it["name"], size=size, sha=ver["sha"], note=ver["note"], everyone=it["everyone"])
        try:
            for attempt in range(4):
                st, r = self.call(peer, "POST", "/api/p2p/offer", offer)
                if st != 200: raise RuntimeError(r.get("error") or f"HTTP {st}")
                if r.get("status") == "unchanged":
                    tr.update(status="unchanged", done=size, end=time.time()); return "unchanged"
                if r.get("status") != "accepted": raise RuntimeError(r.get("error") or "refused")
                try:
                    self._stream(peer, tr, path, int(r.get("offset", 0)), size); break
                except (OSError, http.client.HTTPException) as e:
                    log.warning("transfer %s interrupted at %d: %s (retry %d)", tid[:8], tr["done"], e, attempt + 1)
                    tr["status"] = "Reconnecting"; tr["retries"] = attempt + 1; time.sleep(1 + attempt)
            else:
                raise RuntimeError("connection kept failing")
            tr.update(status="sent", end=time.time()); return "sent"
        except Exception as e:
            log.warning("send to %s failed: %s", peer.get("name"), e)
            tr.update(status="failed: " + str(e), end=time.time()); return "failed"

    def _stream(self, peer, tr, path, off, size):
        tpath = f"/api/p2p/data/{tr['tid']}?offset={off}"
        c = self._conn(peer, timeout=60)
        try:
            c.putrequest("PUT", tpath, skip_accept_encoding=True)
            c.putheader("Content-Length", str(size - off)); c.putheader("Content-Type", "application/octet-stream")
            c.endheaders()
            tr["status"] = "Sending"; tr["done"] = off; t0 = time.time(); base = off
            abort = int(os.environ.get("BGSHARE_TEST_ABORT_AT", "0") or 0)     # test hook: simulate a dropped link
            with open(path, "rb") as fh:
                fh.seek(off); left = size - off
                while left > 0:
                    b = fh.read(min(CHUNK, left))
                    if not b: raise OSError("file shrank while sending")
                    c.sock.sendall(b); left -= len(b); tr["done"] += len(b)
                    tr["speed"] = (tr["done"] - base) / max(time.time() - t0, 1e-3)
                    if abort and tr["done"] >= abort and not tr.get("aborted_once"):
                        tr["aborted_once"] = True; c.sock.shutdown(socket.SHUT_RDWR); raise OSError("test abort")
            r = c.getresponse(); j = json.loads(r.read() or b"{}")
            if r.status != 200: raise OSError(j.get("error") or f"HTTP {r.status}")
            tr["elapsed"] = time.time() - t0
        finally:
            c.close()

    def _store_snippet(self, sha, raw):
        p = os.path.join(self.dir, "snippets", sha + ".txt")
        if not os.path.exists(p):
            with open(p, "wb") as fh: fh.write(raw)

    def _send_snippet(self, peer, it, vi):
        ver = it["versions"][vi]
        with open(os.path.join(self.dir, "snippets", ver["sha"] + ".txt"), encoding="utf-8") as fh: text = fh.read()
        try:
            st, r = self.call(peer, "POST", "/api/p2p/snippet", dict(self.me, title=it["name"], text=text, note=ver["note"], everyone=it["everyone"]))
            return ("unchanged" if r.get("status") == "unchanged" else "sent") if st == 200 else "failed"
        except OSError as e:
            log.warning("snippet to %s failed: %s", peer["name"], e); return "failed"

    def send_snippet(self, to, title, text, note=""):
        everyone, ids = self.parse_to(to)
        if not everyone and not ids: return 400, {"error": "Choose at least one recipient"}
        if not text.strip(): return 400, {"error": "Type or paste some text first"}
        raw = text.encode("utf-8")
        if len(raw) > SNIPPET_MAX: return 400, {"error": "Snippets are limited to 1 MB"}
        title = (str(title or "").strip() or text.strip().splitlines()[0].strip())[:120]
        if not self._targets(everyone, ids)[0]: return 409, {"error": "None of the selected people are online"}
        sha = hashlib.sha256(raw).hexdigest(); self._store_snippet(sha, raw)
        it, v, same = self.add_out_version("snippet", title, everyone, ids, sha, len(raw), note)
        if same: return 200, {"ok": True, "unchanged": True, "version": v, "title": title, "id": it["iid"]}
        res = self.deliver(it, v - 1)
        return 200, {"ok": True, "version": v, "title": title, "id": it["iid"], "results": res}

    def edit_snippet(self, iid, text, note=""):
        it = self.hist["items"].get(iid)
        if not it or it["kind"] != "snippet": return 404, {"error": "Snippet not found"}
        if it["dir"] == "out":
            return self.send_snippet("everyone" if it["everyone"] else [t["id"] for t in it["to"]], it["name"], text, note)
        return self.send_snippet([it["sender_id"]], it["name"], text, note)      # reply with a new version to the sender

    # ---------------------------------------------------------------- receiving (always accepted)
    def _thread_for(self, sender_id, name, kind):
        k = name.casefold()
        for it in self.hist["items"].values():
            if it["dir"] == "in" and it["kind"] == kind and it.get("sender_id") == sender_id and it["name"].casefold() == k:
                return it
        return None

    def _part_size(self, tid):
        p = os.path.join(self.dir, "tmp", tid + ".part")
        return os.path.getsize(p) if os.path.exists(p) else 0

    def _sender(self, o, ip):
        pid = str(o.get("id", ""))
        if not HEX32.fullmatch(pid) or pid == self.cfg["id"]: return None
        try: port = int(o.get("port", DEFAULT_PORT))
        except (TypeError, ValueError): return None
        self.upsert_peer(pid, o.get("name", ""), ip, port)
        return pid

    def handle_offer(self, o, ip):
        tid = str(o.get("tid", ""))
        pid = self._sender(o, ip)
        name = safe_name(o.get("fname")); sha = str(o.get("sha", ""))
        try: size = int(o.get("size", -1))
        except (TypeError, ValueError): size = -1
        if not pid or not HEX32.fullmatch(tid) or not name or not re.fullmatch(r"[0-9a-f]{64}", sha) or size < 0:
            return 400, {"error": "bad offer"}
        with self.lock:
            ex = self.offers_in.get(tid)
            if ex:
                if ex["sender_id"] != pid: return 403, {"error": "not yours"}
                return 200, {"status": ex["status"], "offset": self._part_size(tid)}
            th = self._thread_for(pid, name, "file")
            if th and th["versions"][-1]["sha"] == sha and th.get("path") and os.path.exists(th["path"]):
                return 200, {"status": "unchanged"}
            self.offers_in[tid] = {"tid": tid, "sender_id": pid, "sender": self.name_of(pid), "ip": ip, "name": name, "size": size,
                                   "sha": sha, "note": str(o.get("note", ""))[:140], "everyone": bool(o.get("everyone")),
                                   "status": "accepted", "time": time.time()}
        return 200, {"status": "accepted", "offset": self._part_size(tid)}

    def receive_data(self, tid, ip, offset, length, rfile):
        off = self.offers_in.get(tid)
        if not off or off["ip"] != ip: return 404, {"error": "unknown transfer"}
        if off["status"] != "accepted": return 409, {"error": "transfer already finished"}
        part = os.path.join(self.dir, "tmp", tid + ".part")
        have = self._part_size(tid)
        if offset > have or offset + length != off["size"]: return 416, {"error": "bad offset", "offset": have}
        tr = self.transfers.setdefault(tid, {"tid": tid, "dir": "in", "name": off["name"], "size": off["size"], "peer": off["sender"],
                                             "peer_id": off["sender_id"], "start": time.time()})
        tr.update(status="Receiving", done=offset); t0 = time.time()
        h = hashlib.sha256() if offset == 0 else None
        with open(part, "r+b" if os.path.exists(part) else "wb") as fh:
            fh.seek(offset); fh.truncate()
            left = length
            while left > 0:
                b = rfile.read(min(CHUNK, left))
                if not b: break
                fh.write(b); left -= len(b); tr["done"] += len(b)
                if h: h.update(b)
                tr["speed"] = (tr["done"] - offset) / max(time.time() - t0, 1e-3)
        if left > 0:
            tr["status"] = "Interrupted"; return 400, {"error": "incomplete", "offset": self._part_size(tid)}
        digest = h.hexdigest() if h else file_sha256(part)
        if digest != off["sha"]:
            os.remove(part); off["status"] = "failed"; tr["status"] = "failed: checksum mismatch"
            return 422, {"error": "checksum mismatch"}
        item, v = self._finalize_file(off, part)
        off["status"] = "done"; tr.update(status="received", end=time.time(), iid=item["iid"])
        self.log_event("receive", "file", off["size"], category(off["name"]), off["sender_id"])
        title = f"{off['sender']} sent you a file" if v == 1 else f"{off['sender']} sent a new version (v{v})"
        self.notifier.notify(title, f"{off['name']} ({human(off['size'])})", item["iid"])
        return 200, {"ok": True, "version": v}

    def _finalize_file(self, off, part):
        with self.lock:
            dl = self.cfg["download_dir"]; os.makedirs(dl, exist_ok=True)
            item = self._thread_for(off["sender_id"], off["name"], "file")
            ver = {"sha": off["sha"], "size": off["size"], "time": time.time(), "note": off["note"]}
            if item and item.get("path") and os.path.exists(item["path"]):
                cur = item["versions"][-1]["sha"]; arch = os.path.join(self.dir, "versions", cur)
                if not os.path.exists(arch): shutil.move(item["path"], arch)
                else: os.remove(item["path"])
                shutil.move(part, item["path"])
            else:
                dest = unique_path(dl, off["name"]); shutil.move(part, dest)
                if not item:
                    item = {"iid": secrets.token_hex(8), "dir": "in", "kind": "file", "name": off["name"], "sender_id": off["sender_id"],
                            "versions": [], "read": 0}
                    self.hist["items"][item["iid"]] = item
                item["path"] = dest
            item.update(sender=off["sender"], time=ver["time"], size=off["size"], everyone=off["everyone"], deleted=False)
            item["versions"].append(ver); self.save_hist()
            return item, len(item["versions"])

    def receive_snippet(self, o, ip):
        pid = self._sender(o, ip)
        text = str(o.get("text", "")); raw = text.encode("utf-8")
        if not pid or not text.strip() or len(raw) > SNIPPET_MAX: return 400, {"error": "bad snippet"}
        title = (str(o.get("title", "")).strip() or "Snippet")[:120]
        sha = hashlib.sha256(raw).hexdigest(); self._store_snippet(sha, raw)
        with self.lock:
            item = self._thread_for(pid, title, "snippet")
            if item and item["versions"][-1]["sha"] == sha: return 200, {"status": "unchanged"}
            if not item:
                item = {"iid": secrets.token_hex(8), "dir": "in", "kind": "snippet", "name": title, "sender_id": pid, "versions": [], "read": 0}
                self.hist["items"][item["iid"]] = item
            item["versions"].append({"sha": sha, "size": len(raw), "time": time.time(), "note": str(o.get("note", ""))[:140]})
            item.update(sender=self.name_of(pid), time=time.time(), size=len(raw), everyone=bool(o.get("everyone")), deleted=False)
            self.save_hist(); v = len(item["versions"])
        self.log_event("receive", "snippet", len(raw), "snippet", pid)
        self.notifier.notify(f"{item['sender']} sent you a snippet" if v == 1 else f"{item['sender']} updated a snippet (v{v})", title, item["iid"])
        return 200, {"status": "stored", "version": v}

    # ---------------------------------------------------------------- local history
    def version_path(self, item, vi=None):
        if vi is None: vi = len(item["versions"]) - 1
        if not 0 <= vi < len(item["versions"]): return None
        v = item["versions"][vi]
        if item["kind"] == "snippet":
            p = os.path.join(self.dir, "snippets", v["sha"] + ".txt"); return p if os.path.exists(p) else None
        if item["dir"] == "in" and item.get("path") and os.path.exists(item["path"]) and item["versions"][-1]["sha"] == v["sha"]:
            return item["path"]
        p = os.path.join(self.dir, "versions", v["sha"])
        return p if os.path.exists(p) else None

    def read_text(self, item, vi=None, limit=2 * 1024 * 1024):
        p = self.version_path(item, vi)
        if not p: return None
        with open(p, "rb") as fh: raw = fh.read(limit + 1)
        if len(raw) > limit or b"\x00" in raw[:8192]: return None
        try: return raw.decode("utf-8")
        except UnicodeDecodeError: return raw.decode("latin-1")

    def restore(self, item, vi):
        if not 0 <= vi < len(item["versions"]) - 1: return 400, {"error": "That is already the latest version"}
        src = self.version_path(item, vi)
        if not src: return 404, {"error": "That version is no longer stored on this PC"}
        v = item["versions"][vi]
        if item["dir"] == "out":
            with self.lock:
                item["versions"].append({"sha": v["sha"], "size": v["size"], "time": time.time(), "note": f"Restored v{vi + 1}", "status": {}})
                item["time"] = time.time(); item["size"] = v["size"]; self.save_hist(); n = len(item["versions"])
            self.log_event("restore", item["kind"], v["size"], category(item["name"], item["kind"]))
            threading.Thread(target=self.deliver, args=(item, n - 1), daemon=True).start()
            return 200, {"ok": True, "version": n}
        with self.lock:
            if item["kind"] == "file":
                cur = item["versions"][-1]["sha"]; arch = os.path.join(self.dir, "versions", cur)
                path = item.get("path") or unique_path(self.cfg["download_dir"], item["name"])
                if os.path.exists(path):
                    if not os.path.exists(arch): shutil.move(path, arch)
                    else: os.remove(path)
                os.makedirs(os.path.dirname(path), exist_ok=True)
                shutil.copyfile(src, path + ".bgtmp"); os.replace(path + ".bgtmp", path); item["path"] = path
            item["versions"].append({"sha": v["sha"], "size": v["size"], "time": time.time(), "note": f"Restored v{vi + 1}", "by_me": True})
            item["read"] = len(item["versions"]); item["time"] = time.time(); item["size"] = v["size"]; self.save_hist()
            n = len(item["versions"])
        self.log_event("restore", item["kind"], v["size"], category(item["name"], item["kind"]))
        return 200, {"ok": True, "version": n}

    def diff(self, item, a, b):
        ta, tb = self.read_text(item, a), self.read_text(item, b)
        if ta is None or tb is None: return None
        return "".join(difflib.unified_diff(ta.splitlines(True), tb.splitlines(True), f"v{a + 1}", f"v{b + 1}", n=3))

    def mark_read(self, item):
        if item["dir"] == "in":
            with self.lock: item["read"] = len(item["versions"]); self.save_hist()

    def delete(self, item):
        with self.lock: item["deleted"] = True; item["deleted_at"] = time.time(); self.save_hist()

    # ---- views in the same shape the BGShare UI uses
    def file_obj(self, it):
        v = it["versions"][-1]; me = self.cfg.get("name", "")
        o = {"id": it["iid"], "name": it["name"], "size": v["size"], "time": v["time"], "note": v.get("note", ""),
             "kind": it["kind"], "version": len(it["versions"]), "versions": len(it["versions"]),
             "deleted": bool(it.get("deleted")), "deleted_at": it.get("deleted_at"), "can_delete": True, "dir": it["dir"],
             "uploader_name": it.get("sender", "") if it["dir"] == "in" else me,
             "unread": it["dir"] == "in" and not it.get("deleted") and len(it["versions"]) > it.get("read", 0)}
        if it["dir"] == "out":
            o["to"] = "everyone" if it["everyone"] else [{"id": t["id"], "name": self.name_of(t["id"])} for t in it["to"]]
            o["status"] = v.get("status", {})
        else:
            o["to"] = "everyone" if it.get("everyone") else [{"id": self.cfg["id"], "name": me}]
            o["exists"] = bool(self.version_path(it))
        if it["kind"] == "snippet":
            t = self.read_text(it) or ""
            o["lines"] = t.count("\n") + 1 if t else 0; o["preview"] = "\n".join(t.splitlines()[:8])[:600]
            o["truncated"] = len(o["preview"]) < len(t.rstrip("\n"))
        return o

    def files(self, view):
        with self.lock: its = list(self.hist["items"].values())
        if view == "archive": sel = [i for i in its if i.get("deleted")]
        else:
            its = [i for i in its if not i.get("deleted")]
            sel = {"inbox": [i for i in its if i["dir"] == "in"],
                   "sent": [i for i in its if i["dir"] == "out"],
                   "everyone": [i for i in its if i.get("everyone")],
                   "snippets": [i for i in its if i["kind"] == "snippet"]}.get(view, [])
        return [self.file_obj(i) for i in sorted(sel, key=lambda i: -i["versions"][-1]["time"])]

    def history(self, it):
        me = self.cfg.get("name", "")
        vs = []
        for i, v in enumerate(it["versions"]):
            by = me if it["dir"] == "out" or v.get("by_me") else it.get("sender", "")
            vs.append({"v": i + 1, "by_name": by, "note": v.get("note", ""), "time": v["time"], "size": v["size"], "sha": v["sha"],
                       "available": bool(self.version_path(it, i)), "status": v.get("status")})
        f = self.file_obj(it); f["owner_name"] = it.get("sender", "") if it["dir"] == "in" else me
        return {"file": f, "versions": vs[::-1]}

    def unread_list(self):
        with self.lock:
            return [{"id": i["iid"], "version": len(i["versions"]), "by": i.get("sender", ""), "name": i["name"], "kind": i["kind"]}
                    for i in self.hist["items"].values() if i["dir"] == "in" and not i.get("deleted") and len(i["versions"]) > i.get("read", 0)]

    def unread(self): return len(self.unread_list())

    # ---------------------------------------------------------------- stats
    def _period_start(self, period, now=None):
        lt = time.localtime(now or time.time())
        midnight = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday, 0, 0, 0, 0, 0, -1))
        return {"today": midnight, "week": midnight - lt.tm_wday * 86400, "month": midnight - (lt.tm_mday - 1) * 86400}.get(period, 0), midnight

    def stats_me(self, days=30):
        periods = {}
        for p in ("today", "week", "month", "all"):
            start, _ = self._period_start(p); evs = [e for e in self.events if e["t"] >= start]
            def agg(e, k, evs=evs):
                s = [x for x in evs if x["e"] == e and x["k"] == k]; return {"count": len(s), "bytes": sum(x["b"] for x in s)}
            periods[p] = {"files_sent": agg("send", "file"), "files_received": agg("receive", "file"),
                          "snippets_sent": agg("send", "snippet"), "snippets_received": agg("receive", "snippet")}
        _, midnight = self._period_start("today"); series = []
        for d in range(days - 1, -1, -1):
            a = midnight - d * 86400; b = a + 86400; day = [e for e in self.events if a <= e["t"] < b]
            s = [e for e in day if e["e"] == "send"]; r = [e for e in day if e["e"] == "receive"]
            series.append({"day": time.strftime("%Y-%m-%d", time.localtime(a)), "sent": len(s), "sent_bytes": sum(e["b"] for e in s),
                           "down": len(r), "down_bytes": sum(e["b"] for e in r)})
        return {"periods": periods, "series": series}

    def stats_team(self, period="week"):
        start, _ = self._period_start(period); evs = [e for e in self.events if e["t"] >= start]
        cats = {c: {"sent": 0, "sent_bytes": 0, "down": 0, "down_bytes": 0} for c in CATS}
        people = set(); tot = {"sent": 0, "sent_bytes": 0, "down": 0, "down_bytes": 0}
        for e in evs:
            if e["e"] not in ("send", "receive"): continue
            k = "sent" if e["e"] == "send" else "down"
            c = cats.setdefault(e["c"], {"sent": 0, "sent_bytes": 0, "down": 0, "down_bytes": 0})
            c[k] += 1; c[k + "_bytes"] += e["b"]; tot[k] += 1; tot[k + "_bytes"] += e["b"]
            for p in str(e.get("p") or "").split(","):
                if p: people.add(p)
        tot["active_people"] = len(people)
        return {"period": period, "totals": tot, "categories": cats}


# ---------------------------------------------------------------- HTTP handler
def make_handler(peer):
    class H(BaseHTTPRequestHandler):
        server_version = "BGShare/" + VERSION
        protocol_version = "HTTP/1.1"
        rbufsize = CHUNK

        def log_message(self, fmt, *a):
            log.debug("%s %s", self.client_address[0], fmt % a)

        def j(self, code, obj):
            b = json.dumps(obj).encode()
            self.send_response(code); self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(b))); self.send_header("Cache-Control", "no-store"); self.end_headers()
            self.wfile.write(b)

        def raw(self, code, ctype, b, cache=False):
            self.send_response(code); self.send_header("Content-Type", ctype); self.send_header("Content-Length", str(len(b)))
            self.send_header("Cache-Control", "max-age=86400" if cache else "no-store"); self.end_headers(); self.wfile.write(b)

        def body(self, limit=4 * 1024 * 1024):
            n = int(self.headers.get("Content-Length") or 0)
            if n > limit: raise ValueError("body too large")
            return self.rfile.read(n) if n else b""

        def is_local(self):
            if self.client_address[0] not in ("127.0.0.1", "::1"): return False
            host = (self.headers.get("Host") or "").rsplit(":", 1)[0].strip("[]")
            return host in ("127.0.0.1", "localhost", "::1")

        def local_ok(self, q):
            tok = self.headers.get("X-BG-Local") or (q.get("t") or [""])[0]
            return hmac.compare_digest(tok, peer.local_token)

        def do_GET(self): self.route("GET")
        def do_POST(self): self.route("POST")
        def do_PUT(self): self.route("PUT")
        def do_DELETE(self): self.route("DELETE")

        def route(self, m):
            u = urlparse(self.path); p = u.path; q = parse_qs(u.query)
            try:
                if p.startswith("/api/p2p/"): return self.p2p(m, p, q)
                if not self.is_local(): return self.j(403, {"error": "the BGShare window is only available on this PC"})
                if m == "GET" and p in ("/", "/index.html"):
                    return self.raw(200, "text/html; charset=utf-8", PAGE.replace("__LOCAL_TOKEN__", peer.local_token).encode())
                if m == "GET" and p == "/favicon.svg": return self.raw(200, "image/svg+xml", FAVICON.encode(), True)
                if m == "GET" and p.startswith("/fonts/") and p[7:] in FONTS:
                    return self.raw(200, "font/woff2", base64.b64decode(FONTS[p[7:]]), True)
                if not self.local_ok(q): return self.j(401, {"error": "missing local token"})
                return self.local(m, p, q)
            except (BrokenPipeError, ConnectionResetError):
                return
            except Exception as e:
                log.exception("request failed: %s %s", m, p)
                try: self.j(500, {"error": str(e)})
                except OSError: pass

        # ---------------- peer API (any BGShare PC on the LAN)
        def p2p(self, m, p, q):
            ip = self.client_address[0]
            if m == "GET" and p == "/api/p2p/info":
                return self.j(200, {"app": APP, "proto": PROTO, "version": VERSION, "id": peer.cfg["id"], "name": peer.cfg.get("name", ""), "port": peer.port})
            if m == "PUT" and p.startswith("/api/p2p/data/"):
                tid = p.rsplit("/", 1)[1]
                try: off = int((q.get("offset") or ["0"])[0])
                except ValueError: return self.j(400, {"error": "bad offset"})
                code, obj = peer.receive_data(tid, ip, off, int(self.headers.get("Content-Length") or 0), self.rfile)
                if code != 200: self.close_connection = True
                return self.j(code, obj)
            if m != "POST": return self.j(404, {"error": "not found"})
            try: o = json.loads(self.body() or b"{}")
            except ValueError: return self.j(400, {"error": "bad json"})
            if not isinstance(o, dict): return self.j(400, {"error": "bad json"})
            if p == "/api/p2p/offer": return self.j(*peer.handle_offer(o, ip))
            if p == "/api/p2p/snippet": return self.j(*peer.receive_snippet(o, ip))
            return self.j(404, {"error": "not found"})

        # ---------------- local UI API (same shapes as the BGShare server UI)
        def item(self, iid):
            it = peer.hist["items"].get(iid)
            if not it: self.j(404, {"error": "Not found"})
            return it

        def vnum(self, q, key="v"):
            v = q.get(key)
            return int(v[0]) - 1 if v and v[0].isdigit() else None

        def local(self, m, p, q):
            parts = p.strip("/").split("/")
            if m == "GET":
                if p == "/api/me":
                    if not peer.ready: return self.j(200, {"setup": True, "suggested": default_name()})
                    ul = peer.unread_list()
                    return self.j(200, dict(peer.me, unread=ul, unseen=len(ul), version=VERSION, ips=lan_ips(),
                                            download_dir=peer.cfg["download_dir"], online=len(peer.online_peers())))
                if p == "/api/users": return self.j(200, peer.team())
                if p == "/api/files": return self.j(200, peer.files((q.get("view") or ["inbox"])[0]))
                if p == "/api/stats/me": return self.j(200, peer.stats_me(int((q.get("days") or ["30"])[0])))
                if p == "/api/stats/team": return self.j(200, peer.stats_team((q.get("period") or ["week"])[0]))
                if p == "/api/local/notifications": return self.j(200, {"items": getattr(peer.notifier, "items", [])})
                if p == "/api/local/transfers": return self.j(200, {"transfers": list(peer.transfers.values())})
                if len(parts) == 3 and parts[:2] == ["api", "snippets"]:
                    it = self.item(parts[2])
                    if not it: return
                    t = peer.read_text(it, self.vnum(q))
                    return self.j(200, {"text": t}) if t is not None else self.j(404, {"error": "Snippet not found"})
                if len(parts) == 4 and parts[:2] == ["api", "files"]:
                    it = self.item(parts[2])
                    if not it: return
                    if parts[3] == "history": return self.j(200, peer.history(it))
                    if parts[3] == "diff":
                        a, b = self.vnum(q, "a"), self.vnum(q, "b")
                        d = peer.diff(it, a, b) if a is not None and b is not None else None
                        return self.j(200, {"diff": d}) if d is not None else self.j(415, {"error": "Only text files can be compared"})
                if len(parts) >= 2 and parts[0] == "f":
                    it = self.item(parts[1])
                    if not it: return
                    vi = self.vnum(q)
                    if vi is None: peer.mark_read(it)
                    return self.serve_file(peer.version_path(it, vi), it["name"])
                return self.j(404, {"error": "Not found"})
            if m == "PUT" and p == "/api/upload":
                g = lambda k: (q.get(k) or [""])[0]
                return self.j(*peer.send_upload(g("name"), int(self.headers.get("Content-Length") or 0), self.rfile, g("to"), g("note")))
            if m == "DELETE" and len(parts) == 3 and parts[:2] == ["api", "files"]:
                it = self.item(parts[2])
                if not it: return
                peer.delete(it); return self.j(200, {"ok": True})
            try: o = json.loads(self.body() or b"{}")
            except ValueError: return self.j(400, {"error": "bad json"})
            if p == "/api/settings": return self.j(200, self.settings(o))
            if p == "/api/snippets":
                if o.get("id"): return self.j(*peer.edit_snippet(str(o["id"]), str(o.get("text", "")), str(o.get("note", ""))))
                return self.j(*peer.send_snippet(o.get("to", []), o.get("title", ""), str(o.get("text", "")), str(o.get("note", ""))))
            if len(parts) == 4 and parts[:2] == ["api", "files"]:
                it = self.item(parts[2])
                if not it: return
                if parts[3] == "restore":
                    vi = self.vnum(q)
                    return self.j(*peer.restore(it, -1 if vi is None else vi))
                if parts[3] == "copied":
                    peer.mark_read(it); peer.log_event("copy", "snippet", it["versions"][-1]["size"], "snippet", it.get("sender_id"))
                    return self.j(200, {"ok": True})
                if parts[3] == "copy":
                    t = peer.read_text(it, self.vnum(q))
                    if t is None: return self.j(404, {"ok": False, "error": "Snippet not found"})
                    if copy_to_clipboard(t): return self.j(200, {"ok": True, "native": True})
                    return self.j(501, {"ok": False, "text": t, "error": "native clipboard unavailable"})
                if parts[3] in ("open", "reveal"):
                    peer.mark_read(it)
                    return self.j(200, {"ok": open_path(peer.version_path(it), parts[3] == "reveal")})
            return self.j(404, {"error": "Not found"})

        def settings(self, o):
            c = peer.cfg
            with peer.lock:
                if "name" in o:
                    n = re.sub(r"\s+", " ", str(o["name"])).strip()[:40]
                    if not n: return {"ok": False, "error": "Enter a display name"}
                    c["name"] = n
                if o.get("download_dir"):
                    d = os.path.abspath(os.path.expanduser(str(o["download_dir"])))
                    os.makedirs(d, exist_ok=True); c["download_dir"] = d
                if "notify" in o: c["notify"] = bool(o["notify"])
                peer.save_cfg()
            peer.announce()
            return {"ok": True, "name": c.get("name"), "download_dir": c["download_dir"]}

        def serve_file(self, path, name):
            if not path or not os.path.exists(path): return self.j(404, {"error": "This version is no longer stored on this PC"})
            size = os.path.getsize(path); start, end = 0, size - 1; code = 200
            mt = re.fullmatch(r"bytes=(\d*)-(\d*)", self.headers.get("Range") or "")
            if mt and size:
                a, b = mt.groups()
                if a == "": start = max(0, size - int(b or 0))
                else: start = int(a); end = min(int(b), size - 1) if b else size - 1
                if start > end or start >= size:
                    self.send_response(416); self.send_header("Content-Range", f"bytes */{size}"); self.send_header("Content-Length", "0"); return self.end_headers()
                code = 206
            self.send_response(code)
            self.send_header("Content-Type", mimetypes.guess_type(name)[0] or "application/octet-stream")
            self.send_header("Content-Disposition", "attachment; filename*=UTF-8''" + quote(name))
            self.send_header("Accept-Ranges", "bytes"); self.send_header("Content-Length", str(end - start + 1))
            if code == 206: self.send_header("Content-Range", f"bytes {start}-{end}/{size}")
            self.end_headers()
            with open(path, "rb") as fh:
                fh.seek(start); left = end - start + 1
                while left > 0:
                    b = fh.read(min(CHUNK, left))
                    if not b: break
                    self.wfile.write(b); left -= len(b)
    return H


# ---------------------------------------------------------------- logging / main
def setup_logging(path=None, level=logging.INFO):
    path = path or os.path.join(app_dir(), "bgshare.log")
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    from logging.handlers import RotatingFileHandler
    root = logging.getLogger(); root.setLevel(level)
    fh = RotatingFileHandler(path, maxBytes=2 * 1024 * 1024, backupCount=3, encoding="utf-8")
    fh.setFormatter(logging.Formatter("%(asctime)s %(levelname)s [%(threadName)s] %(message)s")); root.addHandler(fh)
    if sys.stderr:
        sh = logging.StreamHandler(sys.stderr); sh.setFormatter(logging.Formatter("%(asctime)s %(message)s")); root.addHandler(sh)
    def hook(t, v, tb): logging.getLogger("bgshare").critical("unhandled exception", exc_info=(t, v, tb))
    sys.excepthook = hook
    threading.excepthook = lambda a: hook(a.exc_type, a.exc_value, a.exc_traceback)
    return path

def main(argv=None):
    ap = argparse.ArgumentParser(description="BGShare peer")
    ap.add_argument("--headless", action="store_true", help="run without a window (service/test mode)")
    ap.add_argument("--port", type=int, default=DEFAULT_PORT)
    ap.add_argument("--discovery-port", type=int, default=DISCOVERY_PORT)
    ap.add_argument("--data-dir"); ap.add_argument("--download-dir"); ap.add_argument("--name")
    ap.add_argument("--log")
    a = ap.parse_args(argv)
    setup_logging(a.log or os.path.join(a.data_dir or app_dir(), "bgshare.log"))
    p = Peer(a.data_dir, a.port, a.discovery_port, a.name, a.download_dir)
    p.start()
    print(f"BGShare peer '{p.cfg.get('name')}' at http://127.0.0.1:{p.port}/  (LAN: {', '.join(lan_ips())})", flush=True)
    try:
        while True: time.sleep(3600)
    except KeyboardInterrupt:
        p.stop()

